// 降序技巧：写两个 Job，或用 TreeMap 在 Reduce 端排序后输出
// 最简单：Reducer 里先收进 TreeMap，cleanup 时倒序写出
private TreeMap<Integer, String> tm = new TreeMap<>();
public void reduce(Text key, Iterable<IntWritable> vals, Context ctx) {
    int sum = 0; for (IntWritable v : vals) sum += v.get();
    tm.put(sum, key.toString());
}
protected void cleanup(Context ctx) {
    tm.descendingMap().forEach((c, k) -> { /* write (k, c) */ });
}

