CREATE DATABASE IF NOT EXISTS test DEFAULT CHARSET utf8mb4;
USE test;

CREATE TABLE stu (
  sno VARCHAR(20) PRIMARY KEY,
  sname VARCHAR(50) NOT NULL,
  dept VARCHAR(50),
  class VARCHAR(50)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE course (
  cno VARCHAR(20) PRIMARY KEY,
  cname VARCHAR(50),
  credit INT
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE score (
  sno VARCHAR(20),
  cno VARCHAR(20),
  grade DECIMAL(5,2),
  PRIMARY KEY (sno, cno)          -- ⚠ 联合主键这么写，不能给两列各写一个 PRIMARY KEY
) DEFAULT CHARSET=utf8mb4;

